INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(7792, 'koKR', '', '', '', '', 'Wróć do Dugiru na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(7798, 'koKR', '', '', '', '', 'Wróć do Dugiru na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9501, 'koKR', '', 'Potężny żywiołak wody imieniem Aqueous prosi cię do siebie. Wygląda na to, że w żywiole wody na Wyspie Krwawej Mgły doszło do wielkiego zachwiania równowagi. Nic dziwnego, zważywszy na nienaturalne skłonności krwawych elfów.$B$BAqueous znajdziesz na ukrytej rafie pod falami, przy północnym brzegu Wyspy Krwawej Mgły.$B$BWeź ten eliksir – gdy wejdziesz do wody w pobliżu rafy, pomoże ci do niej dotrzeć.', 'Porozmawiaj z Aqueous na Ukrytej Rafie przy Wyspie Krwawej Mgły.', '', '', '', '', '', '', 0),
(9509, 'koKR', '', 'Zatrzymałam odrobinę wody z Jesionowej Kniei – nie dlatego, że wątpiłam, czy sobie poradzisz. Przeciwnie, wiedziałam, że ci się uda, i chciałam, żebyś $gmiał:miała; coś wyjątkowego dla Nobundo.$B$BProszę, $N, weź tę flaszkę czystej wody. Dzięki niej otrzymasz bardzo potężny totem wody.$B$BWieszcz Nobundo czeka na twój powrót w Exodarze.', 'Zanieś Flaszkę najczystszej wody wieszczowi Nobundo w Exodarze na Wyspie Lazurowej Mgły.', '', '', '', '', '', '', 0),
(9552, 'koKR', '', 'Wzywa cię wielki duch powietrza, $N, i czas, byś $gusłuchał:usłuchała; jego wezwania.$B$BUdaj się Ścieżką Dzikiego Wiatru na północnym zboczu góry, w którą uderzył Exodar. Na szczycie znajdziesz jaskinię, a w niej jedną z moich najzdolniejszych uczennic, Velaadę.$B$BWysłuchaj, proszę, jej mądrości i zrób, o co cię poprosi. Gdy wrócisz, będziesz lepiej rozumieć żywioł powietrza.', 'Porozmawiaj z Velaadą na Szczycie Dzikiego Wiatru na Wyspie Lazurowej Mgły.', '', '', '', '', '', '', 0),
(9553, 'koKR', '', 'Choć powietrze może wydawać się nieuchwytne, jest siłą wszechobecną, która okrywa i przenika wszystko wokół nas.$B$BChoć tego nie widać, skały tej jaskini składają się w większości z powietrza, wody oceanów są nim nasycone, a bez niego ogień nie mógłby płonąć. Tylko nie powtarzaj tego przy innych żywiołach!$B$BTen, z kim naprawdę chcesz porozmawiać o takiej mądrości, jest niedaleko. Na północnej krawędzi urwiska czeka na ciebie Susurrus. To od niego nauczysz się zrozumienia.', 'Porozmawiaj z Susurrusem na Szczycie Dzikiego Wiatru na Wyspie Lazurowej Mgły.', '', '', '', '', '', '', 0),
(9554, 'koKR', '', 'Choć moi bracia i siostry z innych żywiołów żądali od ciebie wykonania różnych zadań, ja o nic więcej cię nie poproszę. Myślę, że $gzrobiłeś:zrobiłaś; dość, by „odpokutować” za to, że wasz statek spadł w to miejsce z moich niebios. Widzę, że masz w sobie całą mądrość potrzebną, by rozważnie korzystać z żywiołu powietrza.$B$BZanieś tę cząstkę mojej istoty wieszczowi Nobundo, żeby pomógł ci wykonać totem. A gdy będziesz $ggotów:gotowa;, zniosę cię z powrotem do Exodaru.', 'Wróć z Wirem powietrza do wieszcza Nobundo w Exodarze na Wyspie Lazurowej Mgły.', '', '', '', '', '', '', 0),
(9555, 'koKR', '', 'Jestem wdzięczny, że $gwybrałeś:wybrałaś; trudną ścieżkę szamana. Niewielu to robi, lecz przewiduję, że dla naszej przyszłości kluczowe będzie, byśmy nauczyli się szamanizmu od Złamanych.$B$BTak się ich nazywa, ale niegdyś byli draenei. Przemieniła ich magia Spaczenia i dlatego nie mogą przyzywać mocy Światłości. Niektórzy patrzą krzywo na nich i na szamanizm, którego nauczają, ale nie są oni źli.$B$BChciałbym, żebyś $gporozmawiał:porozmawiała; z wieszczem Nobundo. To najmądrzejszy szaman, jakiego znam, a pod jego okiem wiele się nauczysz.', 'Porozmawiaj z wieszczem Nobundo w Kryształowej Sali w Exodarze.', '', '', '', '', '', '', 0),
(9591, 'koKR', '', 'Gdy $c stawia pierwsze kroki na swojej ścieżce, uczy się tylko zabijać. Wygląda na to, że teraz jesteś $ggotów:gotowa; na więcej.$b$bFurbolgi z Cichej Sosny dały nam sposób na opanowanie sztuki oswajania bez wielomiesięcznej nauki. Potrafią wyrzeźbić totem na podobieństwo zwierzęcia, a ty możesz go użyć, by na jakiś czas związać się ze stworzeniem tego rodzaju.$b$bNa pierwszą lekcję weź ten totem i użyj go na kolczastych pełzaczach, które znajdziesz wzdłuż zachodniego wybrzeża wyspy.', 'Użyj Totemu oswajania, by zjednać sobie kolczastego pełzacza, a gdy ci się uda, wróć do łowczyni Kelli Nocny Łuk.', 'Oswój kolczastego pełzacza', 'Wróć do łowczyni Kelli Nocny Łuk na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9592, 'koKR', '', 'Pełzacz bez wątpienia był wredny, ale leśny biegus wystawi twoją wytrwałość na próbę. Potężniejsi sprzymierzeńcy wymagają od łowcy więcej nieustępliwości.$b$bWeź ten totem oswajania i zjednaj sobie większego leśnego biegusa. Znajdziesz je w północnej części Wyspy Lazurowej Mgły.', 'Użyj Totemu oswajania, by zjednać sobie większego leśnego biegusa, i wróć do łowczyni Kelli Nocny Łuk.', 'Oswój większego leśnego biegusa', 'Wróć do łowczyni Kelli Nocny Łuk na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9593, 'koKR', '', 'Pewnie przy oswajaniu biegusa $gzauważyłeś:zauważyłaś; wielkie koty zwane nocnymi tropicielami. To sprawni i zabójczy łowcy... i sprzymierzeńcy.$b$bUżyj tego totemu oswajania, by zjednać sobie nocnego tropiciela. Poluj razem z tym groźnym kotem i chroń go przed krzywdą. Gdy skończysz, wróć do mnie.', 'Użyj Totemu oswajania, by zjednać sobie nocnego tropiciela, i wróć do łowczyni Kelli Nocny Łuk.', 'Oswój nocnego tropiciela', 'Wróć do łowczyni Kelli Nocny Łuk na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(9598, 'koKR', 'Odkupienie', 'Moim zadaniem jest prowadzić paladynów ścieżką wyższej cnoty, gdy poświęcają się Światłości i bronią naszego ludu przed zagrożeniami.$B$BNadszedł czas, byś $gzrobił:zrobiła; pierwszy krok ku prawdziwej cnocie. Jeśli się na to zgodzisz, dam ci księgę boskości. Studiując ją, dowiesz się czegoś o Światłości i o tym, czego się od ciebie oczekuje. Jeśli ją zrozumiesz i okażesz się $gzdolny:zdolna;, zdobędziesz większe umiejętności.', 'Przestudiuj Księgę Boskości i porozmawiaj z Jol.', '', '', '', '', '', '', 0),
(9600, 'koKR', 'Odkupienie', 'Twoim zadaniem, $N, jest więc pomóc naszym nowym sojusznikom, furbolgom z Cichej Sosny.$b$bKilku młodszych szamanów z Cichej Sosny natknęło się na obóz Szczecinołapych i zostało wyrżniętych do ostatniego. Weź ten Symbol Życia i wskrześ jednego z szamanów.$b$bEnklawa Szczecinołapych leży na wschód od drogi, zaraz za mostem łączącym Wyspę Lazurowej Mgły z Wyspą Krwawej Mgły. Gdy to zrobisz, porozmawiaj ze mną.$B', 'Jol chce, żebyś $gwskrzesił:wskrzesiła; młodego szamana furbolgów Symbolem Życia i $gwrócił:wróciła; do niej.', '', 'Wróć do Jol w Skarbcu Świateł w Exodarze.', 'Wskrzeszony młody szaman furbolgów', '', '', '', 0),
(9604, 'koKR', 'Na skrzydłach hipogryfa', 'Za niewielką opłatą możesz wynająć jednego z moich hipogryfów, który zaniesie cię do Exodaru.$B$BLot hipogryfem to szybszy – nie mówiąc już o tym, że bezpieczniejszy – sposób podróży dla kogoś, kto niesie ważną wiadomość. Jeśli chcesz polecieć, porozmawiaj ze mną jeszcze raz, a wszystko przygotuję.', 'Wykup u Laando lot hipogryfem do Exodaru. Po wylądowaniu zanieś Listę Tophera Nurguni w Siedzibie Naaru w Exodarze.', '', '', '', '', '', '', 0),
(9605, 'koKR', 'Mistrz hipogryfów Stephanos', 'Oto skrzynka, $N. To powinno wystarczyć Topherowi, by uruchomić karczmę. Przekaż mu, że może dalej przysyłać zamówienia, gdy zajdzie potrzeba. Krwawa Strażnica pilnie potrzebuje miejsca, gdzie można opatrywać rannych i przenocować podróżnych.$B$BGdy będziesz $ggotów:gotowa; do powrotu do Krwawej Strażnicy, odszukaj Stephanosa przy bramach Exodaru.', 'Odszukaj Stephanosa przed Exodarem i wykup lot hipogryfem z powrotem do Krwawej Strażnicy.', '', '', '', '', '', '', 0),
(9606, 'koKR', 'Powrót do Tophera Loaala', 'Jeśli dobrze pamiętam, mistrzem hipogryfów w Krwawej Strażnicy jest Laando. Jeśli już z nim $grozmawiałeś:rozmawiałaś;, możesz polecieć do niego jednym z moich hipogryfów.$B$BWarto to wiedzieć: hipogryfy zawsze są szkolone, by latać do swojej stolicy, ale do odległego mistrza hipogryfów zaniosą cię dopiero wtedy, gdy już tam $gbyłeś:byłaś;.$B$BSkoro $gprzyleciałeś:przyleciałaś; na jednym z hipogryfów Laando, możesz też tą trasą wrócić do Krwawej Strażnicy z zapasami dla opiekuna.', 'Wykup u Stephanosa lot hipogryfem z powrotem do Krwawej Strażnicy. Po przybyciu dostarcz Zapasy od Nurguni opiekunowi Topherowi Loaalowi.', '', '', '', '', '', '', 0),
(9632, 'koKR', 'Nowi sojusznicy', 'Zwiastun Mikolaas godnie strzeże Krwawej Strażnicy, $N, ale nasi wrogowie są liczni, a nasze zasoby skromne.$B$BNasi wrogowie dobrze znają naszą słabość, ale nie wzięli pod uwagę twoich kontaktów z siłami Przymierza. Przygotowałem list polecający do mieszkańców Auberdine, najbliższej osady Przymierza, z propozycją współpracy w walce z naszymi wrogami. Weź go i odszukaj łowczynię Kellę Nocny Łuk przy przystani na zachód od Exodaru.', 'Zanieś List polecający łowczyni Kelli Nocny Łuk na Wyspie Lazurowej Mgły.', '', '', '', '', '', '', 0),
(9633, 'koKR', 'Droga do Auberdine', 'Jeśli zaczekasz na pomoście, zobaczysz łódź przypływającą z portu Auberdine na Mrocznym Wybrzeżu. Gdy wysiądą z niej pasażerowie, będziesz $gmógł:mogła; wejść na pokład.$B$BPo krótkiej podróży łódź zawinie do Auberdine i będziesz $gmógł:mogła; dostarczyć swoją wiadomość.$B$BNajlepiej zanieść ją Thundrisowi Wiatrotkaczowi, mojemu staremu przyjacielowi i szanowanemu mieszkańcowi miasta.', 'Popłyń łodzią z pomostu przy łowczyni Kelli Nocny Łuk do Auberdine. Po przybyciu do Auberdine zanieś List polecający Thundrisowi Wiatrotkaczowi.', '', '', '', '', '', '', 0),
(9675, 'koKR', 'Szkolenie bestii', 'Och, jeszcze jedno! Koniecznie porozmawiaj z Ganaarem w Exodarze. Nauczy cię ostatnich rzeczy, które trzeba wiedzieć, by dbać o swojego zwierzaka i go szkolić.$b$bZnajdziesz go w południowo-zachodnim narożniku Tarasu Handlarzy.', 'Porozmawiaj z Ganaarem na Tarasie Handlarzy w Exodarze.', '', '', '', '', '', '', 0),
(9698, 'koKR', 'Audiencja u Proroka', 'Musisz osobiście dostarczyć przetłumaczone dokumenty Velenowi, $N. Nie ufam temu obłąkanemu posłańcowi.$B$BWyjaśnij Prorokowi, że krwawe elfy otrzymują posiłki z Rubieży i że mają szpiega wśród draenei w Exodarze. Velen przebywa w Skarbcu Świateł w Exodarze.$B$BPośpiesz się!$B', 'Zanieś Przetłumaczoną depeszę Słonecznych Jastrzębi Prorokowi Velenowi w Exodarze.', '', '', '', '', '', '', 0),
(9699, 'koKR', 'Prawda czy fikcja', 'Dziękuję za terminowe dostarczenie, $N. Okazujesz się jednym z lepszych agentów Ręki.$B$BGdybyśmy tylko wiedzieli, komu podlegają na Wyspie Krwawej Mgły, a przede wszystkim, gdzie jest ten słoneczny portal... Wygląda na to, że pilnie go strzegą – gdziekolwiek się znajduje.$B$BCzy $gbyłbyś zainteresowany:byłabyś zainteresowana; zadaniem zwiadowczym?$B$BJeśli tak, zanieś te rozkazy obrońcy Borosowi. On przydzieli ci następną misję.', 'Zanieś Rozkazy Velena obrońcy Borosowi w Krwawej Strażnicy.', '', '', '', '', '', '', 0),
(9762, 'koKR', 'Niespisana przepowiednia', '', '', '', '', '', '', '', '', 0),
(10356, 'koKR', '', '', '', '', 'Wróć do Dugiru na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(10357, 'koKR', '', '', '', '', 'Wróć do Dugiru na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(10358, 'koKR', '', '', '', '', 'Wróć do Dugiru na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(10371, 'koKR', '', 'Krasnoludzki wojownik Yorus Jęczmieniowar rzucił wyzwanie wszystkim wprawnym wojownikom Przymierza.$B$BCzeka w karczmie w Jeziernych Włościach, w krainie zwanej Górami Rudej Grani, we Wschodnich Królestwach. Podróż będzie długa, ale warto, byś $gsię sprawdził:się sprawdziła;, $N.', 'Porozmawiaj z Yorusem Jęczmieniowarem w karczmie w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', '', '', 0),
(10956, 'koKR', 'Siedziba Naaru', 'Wiesz coś o naaru? To takie anielskie istoty, które od bardzo dawna pomagają draenei. Widziałam ich mnóstwo w Shattrath.$B$BMówią, że jeden naaru, O\'ros, był na pokładzie Exodaru, kiedy ten poleciał do twojego ojczystego świata. Chciałabym to zobaczyć na własne oczy.$B$BZabierzesz mnie tam? Założę się, że szybko się tam dostaniemy przez któryś z portali na Tarasie Światła w Shattrath! A jak już tam będziemy i się zgubisz, zawsze możemy zajrzeć na twoją mapę.', 'Zaprowadź swoją podopieczną, sierotę Dornaę, przed oblicze O\'rosa na dole Siedziby Naaru w Exodarze, na Wyspie Lazurowej Mgły. Jeśli po przybyciu nie będzie jej przy tobie, przywołaj ją.$B$BPamiętaj, że w mieście możesz korzystać z mapy.', 'Dornaa zaprowadzona do Siedziby Naaru', 'Porozmawiaj z O\'rosem w Exodarze na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(10968, 'koKR', 'Wizyta u wieszcza', 'Wyczuwam w tym dziecku coś naprawdę wyjątkowego.$B$BZabierz ją do wieszcza Nobundo, tutaj, w Exodarze. Wierzę, że spodziewa się was obojga.$B$BSzukaj Nobundo na najwyższym tarasie Kryształowej Sali.', 'Zaprowadź swoją podopieczną, sierotę Dornaę, do wieszcza Nobundo w Kryształowej Sali w Exodarze, na Wyspie Lazurowej Mgły. Jeśli po przybyciu nie będzie jej przy tobie, przywołaj ją.$B$BPamiętaj, że w mieście możesz korzystać z mapy.', 'Dornaa zaprowadzona do wieszcza Nobundo', 'Porozmawiaj z wieszczem Nobundo w Exodarze na Wyspie Lazurowej Mgły.', '', '', '', '', 0),
(12776, 'koKR', 'Exodar', 'Nasze modlitwy zostały wysłuchane! Dzięki skupionej Światłości od naaru z Shattrath i wspólnym błogosławieństwom wiernych stworzyliśmy święte artefakty o ogromnej mocy. Te artefakty będą naszą bronią przeciw knowaniom Króla Lisza.$B$BWeź to, $n. Strzeż go pilnie i bezpiecznie dostarcz do Exodaru. Przekaż go Prorokowi Velenowi w Skarbcu Świateł, by mógł użyć jego mocy przeciw bezbożnym siłom z Północy.', 'Biskup Lazaril chce, żebyś $gdostarczył:dostarczyła; Artefakt nasycony Światłością Velenowi w Exodarze.', '', 'Wróć do Proroka Velena.', '', '', '', '', 0),
(24611, 'koKR', 'Prezent dla Proroka', 'Chcesz zrobić Uroczą bransoletkę z talizmanami dla Proroka Exodaru? Na pewno będzie zachwycony.$B$BMasz już Zestaw kolekcjonera uroczych talizmanów?', 'Podaruj Uroczą bransoletkę z talizmanami Prorokowi Velenowi w Exodarze.', '', 'Wróć do Proroka Velena.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9501, 'koKR', 'Nie lękaj się, $N. Dopóki tu jesteś, będziemy rozmawiać za pomocą umysłów.$B$BJestem wdzięczna wieszczowi Nobundo, że cię do mnie przysłał. Wody na Wyspie Krwawej Mgły i wokół niej zatruwa wielkie zakłócenie. Nawet ślepiec zauważyłby, jak wpływa ono na tutejsze stworzenia i otoczenie.$B$BRazem powstrzymamy to skażenie, zanim rozprzestrzeni się dalej.', 0),
(9509, 'koKR', '$GPostępowałeś:Postępowałaś; z mądrością ponad swoje lata, $N. Czuję, że żywioł wody jest zadowolony z twoich czynów. Będzie dla mnie wielkim zaszczytem przyjąć czystą wodę, którą niesiesz, i połączyć jej esencję z twoim nowym totemem wody.$B$BPamiętaj dobrze nauki wody na dalszej drodze, a zyskasz jeszcze głębsze zrozumienie tego żywiołu i władzę nad nim.', 0),
(9552, 'koKR', 'Wiatry wyszeptały mi, że przybędziesz, $N.$B$BWieszcz Nobundo ma o tobie bardzo wysokie mniemanie, a z tego, co słyszałam o twoich wędrówkach, ja również.', 0),
(9553, 'koKR', 'Oczekiwałem twojego przybycia, $N. Przychodzisz po mądrość i, jak wyczuwam, po coś jeszcze.$B$BDobrze więc, zaczynajmy.', 0),
(9554, 'koKR', 'Jestem z ciebie dumny, $N. $GWytrwałeś:Wytrwałaś; tam, gdzie inni się poddają, i przy okazji lepiej $gpoznałeś:poznałaś; żywioły i $gsamego siebie:samą siebie;. Pamiętaj ich nauki, idąc przez życie, a zyskasz na mądrości.$B$BA teraz daj mi wir od Susurrusa, żebym mógł tchnąć go w twój totem powietrza. Tak jak pozostałe totemy, będzie ci służył zarówno do skupienia, jak i jako przypomnienie więzi, którą $gzadzierzgnąłeś:zadzierzgnęłaś; z żywiołami.', 0),
(9555, 'koKR', 'Witaj. Zawsze podnosi na duchu spotkanie z kimś, kto jest otwarty na drogę szamanizmu. Tak niewielu takich jest.$B$B$GNauczyłeś:Nauczyłaś; się nie oceniać płomienia po wyglądzie, tak jak nie powinno się oceniać mnie.$B$BJesteś tu, bo nadszedł czas, byś $gstworzył:stworzyła; swój totem ognia.', 0),
(9591, 'koKR', 'Założę się, że najpierw $gprzekonałeś:przekonałaś; się, jak mało pełzacz jest skory do współpracy przy tworzeniu więzi. Same szczypce, dopóki nie zrozumie, że nie zamierzasz wrzucić go do wrzątku.', 0),
(9592, 'koKR', 'Wygląda na to, że biegus nie wydziobał ci oczu.$B$B<Kella na chwilę odwraca wzrok.>$B$BNie żebym myślała, że tak się stanie, oczywiście!', 0),
(9593, 'koKR', 'Muszę przyznać, $N, że uczysz się dużo szybciej, niż z początku sądziłam. Wygląda na to, że ten ostatni totem oswajania nie będzie nam potrzebny. I szczerze mówiąc, nawet nie wiem, co przedstawia. Wygląda jak jakaś potworna jaszczurka ze skrzydłami i długim ogonem. Cóż, może innym razem!$B$B$GNabrałeś:Nabrałaś; już dość doświadczenia, by próbować samodzielnie, bez pomocy totemu oswajania. Powodzenia!', 0),
(9598, 'koKR', 'Mam nadzieję, że $gpoświęciłeś:poświęciłaś; czas na lekturę księgi?$B$BW takim razie możesz już zostać $gpoddany:poddana; próbie. Po katastrofie Exodaru na tych nowych ziemiach zawsze jest coś do zrobienia: akty współczucia i zrozumienia... ci, którzy potrzebują pomocy... stworzenia do zabicia...$B$BDowodząc, że masz cierpliwość, by pomagać innym, zwłaszcza tym, którym los mniej sprzyja, udowadniasz, że jesteś $gsługą:służebnicą; Światłości i masz trzeźwy umysł.', 0),
(9600, 'koKR', 'Nie przejmuj się oszołomieniem tych, którym pomagasz. Ci, którzy niedawno wrócili do świata żywych, często są zdezorientowani – a wyobraź sobie jeszcze szok spotkania w tej samej chwili z obcą istotą.$B$BMłody szaman ma szczęście, że dzięki tobie przetrwał tak surową lekcję, i słusznie jest, byś $gmógł:mogła; przywoływać tę moc, kiedy uznasz to za stosowne.', 0),
(9604, 'koKR', 'Więc $gprzyniosłeś:przyniosłaś; listę Tophera. Wspaniale! Miałam nadzieję, że dostanę ją dzisiaj. Zobaczmy, czego potrzebuje.$B$B<Nurguni przegląda listę i zaczyna wkładać różne rzeczy do skrzynki.>$B$BTo większość tego, o co prosił. Części do łóżek są po prostu za duże, by przewieźć je hipogryfem, ale załatwię, żeby wysłano je wozem.', 0),
(9605, 'koKR', 'Więc wracasz z tą paczką do Krwawej Strażnicy? Żaden problem, $N. Porozmawiaj ze mną jeszcze raz, a wyślemy cię w drogę razem z zapasami.', 0),
(9606, 'koKR', '<Wręczając Topherowi skrzynkę, mówisz mu, że Nurguni załatwia dostawę większych rzeczy wozem.>$B$BZnakomicie! Wreszcie będę mógł ustawić kilka łóżek i punkt pierwszej pomocy, żeby lepiej opatrywać rannych i ocalałych, na których natrafimy.$B$BNie potrafię wyrazić, jak bardzo jestem ci wdzięczny za pomoc, $N. Masz moje podziękowania, a także podziękowania obrońców Krwawej Strażnicy.', 0),
(9632, 'koKR', 'Mogę ci pomóc dostać się do Auberdine. Na szczęście to tylko krótki rejs łodzią!', 0),
(9633, 'koKR', '<Thundris bierze od ciebie list i szybko go czyta, kiwając głową.>$B$BWyspy, które twój lud nazywa Lazurową i Krwawą Mgłą, dawno temu zamieszkiwał mój lud. Niektóre z zagrożeń, z którymi mierzą się anachoreta Paetheus i jego bracia, to pradawni wrogowie nocnych elfów.$B$BJestem pewien, że mieszkańcy Auberdine zechcą udzielić naszym nowym sojusznikom takiej pomocy, na jaką nas stać. Gdy tylko porozmawiam z mieszkańcami miasta i strażniczkami, przekażę wiadomość Paetheusowi.', 0),
(9675, 'koKR', 'Umiejętność karmienia zwierzaka i przywracania go do życia to nie jest jakiś dodatkowy „smaczek”, jak łagodnie ujęła to twoja poprzednia nauczycielka. Co więcej, szkolenie pozwala zwierzakowi rozwinąć się w sposób, w jaki sam by nie potrafił.$B$BWiele już się nauczyłem od furbolgów, więc słuchaj uważnie, a przekażę ci tę wiedzę.', 0),
(9698, 'koKR', '<Velen zaczyna czytać dokument.>$B$BCiekawe... To rzeczywiście wiele wyjaśnia.', 0),
(9699, 'koKR', 'To dobry plan, ale niebezpieczny. Jestem pewien, że sobie poradzisz.', 0),
(9762, 'koKR', 'Te wyspy staną się domem dla tysięcy. Większość z nich spędzi tu całe życie. Gdybyś $gzechciał:zechciała;, $gmógłbyś:mogłabyś; zrobić to samo. Ale nie tego pragniesz, prawda, $N?$B$B<Velen kiwa głową.>$B$BZanim odejdziesz z tego świata, dokonasz jeszcze wielu wielkich rzeczy. Musisz przyjąć swoje przeznaczenie i stawić mu czoła!$B$BNim wyruszysz, daję ci dwa dary: ten tabard noszą tylko najbardziej czczeni członkowie Ręki Argusa, a ten sygnet – nasi najmądrzejsi mędrcy. Noś je oba z dumą, $N.', 0),
(10373, 'koKR', 'Witaj na Plagowiskach, $gbohaterze:bohaterko;. To jedno z najniebezpieczniejszych pograniczy w Azeroth, zwłaszcza że na północy i północnym wschodzie czai się zagrożenie ze strony Plagi. Cieszę się, że donośne wezwanie do obowiązku i służby większemu dobru nie trafiło u ciebie w próżnię!$B$BJeśli jesteś $ggotów:gotowa; pobrudzić sobie ręce, to tu, na skraju Plagowisk, jest mnóstwo pracy dla chętnych i zdolnych bohaterów.', 0),
(10956, 'koKR', '<Czujesz raczej, niż słyszysz, jak w twoim umyśle rozbrzmiewa melodyjny głos O\'rosa.>$b$bDziękuję, że $gprzyprowadziłeś:przyprowadziłaś; do mnie to dziecko, $N. Jest naprawdę wyjątkowa i pewnego dnia wyrośnie na ważną postać wśród draenei. W niemałej mierze stanie się tak dzięki życzliwości, jaką jej $gokazałeś:okazałaś;, i wrażeniu, jakie na niej $gwywarłeś:wywarłaś;.', 0),
(10968, 'koKR', 'Miałem nadzieję, ale obawiałem się, że to tylko wytwór mojej wyobraźni. To dziecko jest niesamowite!$b$bW dzisiejszych czasach to niesłychane, by ktoś z draenei przejawiał taki dar do żywiołów bez żadnego szkolenia. Musiała odziedziczyć tę moc po jakimś dawnym przodku.$b$bWyślę list do opiekunki sierot w Shattrath z prośbą, by pozwolono dziecku zamieszkać z nami.$b$bDo tego czasu, proszę, dbaj o jej bezpieczeństwo.', 0),
(12776, 'koKR', 'Ach, widzę, jak moc naaru prześwieca przez ten przedmiot, jakby mieszkała w nim sama Światłość. Tyle dobra można dzięki niemu zdziałać – nekropolie przysłane z mroźnych pustkowi północy z pewnością poniosą klęskę.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(9509, 'koKR', 'Żywioły opowiedziały mi o wielkich czynach, których $gdokonałeś:dokonałaś;. Podejdź, porozmawiajmy.', 0),
(9554, 'koKR', 'Już z powrotem? Masz potargane włosy.$B$B<Nobundo uśmiecha się porozumiewawczo.>', 0),
(9591, 'koKR', 'Czy $gzdołałeś:zdołałaś; wykorzystać magię totemu, by zjednać sobie kolczastego pełzacza? To zadziorne stworzonka!', 0),
(9592, 'koKR', 'Leśny biegus to potężny ptak, często lekceważony przez drapieżniki – z opłakanym dla nich skutkiem.', 0),
(9593, 'koKR', 'Nocny tropiciel to w gruncie rzeczy wielki kotek z ostrymi jak brzytwa pazurami i apetytem na mięso...', 0),
(9598, 'koKR', 'Witaj z powrotem, $N.', 0),
(9600, 'koKR', 'Każde życie jest warte ocalenia, jeśli nie występuje przeciw nam. Tylko nasi wrogowie powinni spocząć na zawsze.', 0),
(9604, 'koKR', 'Witaj, $gprzyjacielu:przyjaciółko;. Wyglądasz, jakby za tobą była długa droga. W czym mogę pomóc?', 0),
(9605, 'koKR', 'Dokąd się wybierasz, $N?', 0),
(9606, 'koKR', 'Witaj z powrotem, $N. Czy Nurguni zdołała zebrać wszystko z listy?', 0),
(9632, 'koKR', 'Witaj, $N. Co tam masz?', 0),
(9633, 'koKR', 'Witaj w Auberdine, $gprzyjacielu:przyjaciółko;. Co sprowadza cię na Mroczne Wybrzeże?', 0),
(9698, 'koKR', '<Velen się uśmiecha.>$B$BWitaj, $N. Spodziewałem się ciebie.', 0),
(9699, 'koKR', 'No i?', 0),
(12776, 'koKR', '$GMój synu:Moja córko;, ziemie ludzi i orków dobrze ci posłużyły. Taka siła wzbiera teraz w tobie...', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(3649, 0, 'koKR', 'Mroczne siły napierają na nasze granice, odżywają pradawne skażenia, a nowe zło powstaje, by zburzyć kruchą równowagę tej ziemi. W czasach takiej ciemności wszyscy musimy zachować czujność.', 0);
