INSERT INTO `item_template_locale` (`ID`, `locale`, `Name`, `Description`, `VerifiedBuild`) VALUES
(7337, 'koKR', 'Głaz', 'Ależ on wielki!', 0),
(7338, 'koKR', 'Pierścień nastroju', 'Jest niebieski... nie, czekaj, zielony!', 0),
(7339, 'koKR', 'Pierścień z maleńkim diamentem', 'Ale to wciąż diament.', 0),
(7340, 'koKR', 'Soliter z nieskazitelnym diamentem', 'Wyjdziesz za mnie?', 0),
