(22565, 'koKR', 'Formuła: duży pryzmatyczny odłamek', 'Uczy łączenia małych pryzmatycznych odłamków w duży pryzmatyczny odłamek.', 0),
(22900, 'koKR', 'Receptura: eliksir kamuflażu', 'Uczy warzenia eliksiru kamuflażu.', 0),
(23574, 'koKR', 'Receptura: transmutacja pierwotnej potęgi', 'Uczy transmutacji pierwotnego powietrza, wody, ziemi, ognia i many w pierwotną potęgę.', 0),
(23590, 'koKR', 'Plany: młot z adamantytu', 'Uczy wykuwania młota z adamantytu.', 0),
(23591, 'koKR', 'Plany: tasak z adamantytu', 'Uczy wykuwania tasaka z adamantytu.', 0),
