(23593, 'koKR', 'Plany: rapier z adamantytu', 'Uczy wykuwania rapiera z adamantytu.', 0),
(23752, 'koKR', 'Flaszka najczystszej wody', 'Woda w środku promieniuje mocą czystości.', 0),
(23799, 'koKR', 'Schemat: strzelba z adamantytu', 'Uczy konstruowania strzelby z adamantytu.', 0),
(23811, 'koKR', 'Schemat: biała raca dymna', 'Uczy konstruowania białej racy dymnej.', 0),
(23815, 'koKR', 'Schemat: maszyna do łusek z adamantytu', 'Uczy konstruowania maszyny do łusek z adamantytu.', 0),
(23816, 'koKR', 'Schemat: skrzynka na narzędzia ze spaczonego żelaza', 'Uczy konstruowania skrzynki na narzędzia ze spaczonego żelaza.', 0),
(23843, 'koKR', 'Wir powietrza', 'Zawirowanie oderwane od Susurrusa jakimś cudem nie rozpada się w twojej dłoni.', 0),
(23871, 'koKR', 'Mikstura oddychania pod wodą', '', 0),
(23896, 'koKR', 'Totem oswajania', '', 0),
(23897, 'koKR', 'Totem oswajania', '', 0),
(23898, 'koKR', 'Totem oswajania', '', 0),
(23902, 'koKR', 'Lista Tophera', 'Lista rzeczy najpilniej potrzebnych w karczmie w Krwawej Strażnicy.', 0),
(23903, 'koKR', 'Zapasy od Nurguni', 'Skrzynia pełna materiałów budowlanych, środków pierwszej pomocy i innych rzeczy dla karczmy w Krwawej Strażnicy.', 0),
(23937, 'koKR', 'List polecający', 'List napisany przez anachoretę Paetheusa.', 0),
