INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2943, 'koKR', 'Orędzie Króla Słońca$B$BSłoneczne Jastrzębie – moje drogie, wierne dzieci – wasz król wyraża wam uznanie. Wasza obecność w Azeroth ma najwyższe znaczenie zarówno dla mnie, jak i dla Pana.$B$BWkrótce słoneczny portal będzie gotów przerzucić posiłki z Twierdzy Burz prosto na Wyspę Krwawej Mgły.$B$BOdbijemy Exodar. Wybijemy tych niebieskoskórych kundli tam, gdzie stoją. Velen zapłaci za swoje zbrodnie.$B$B– Król Kael\'thas Słońcobieżca', 0),
(2994, 'koKR', 'We wszystkim paladyni muszą odzwierciedlać Światłość, która dopełnia naszą siłę. Dążyć do boskości nie znaczy dla kogoś z nas dążyć do stania się bogiem – dążymy do tego, by być dobrymi we wszystkich czynach.', 0),
(2995, 'koKR', 'Choć w tych surowych czasach wzywa się nas do karania zła, musisz zawsze pamiętać, że to pomoc innym naprawdę wyróżni cię spośród pozostałych mieszkańców. Współczucie, cierpliwość, odwaga – te rzeczy znaczą dla paladyna tyle samo co siła w boju.$B$BZapamiętaj to dobrze i nigdy nie zapominaj.', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(50024, 'koKR', 'Mroczne siły napierają na nasze granice, odżywają pradawne skażenia, a nowe zło powstaje, by zburzyć kruchą równowagę tej ziemi. W czasach takiej ciemności wszyscy musimy zachować czujność.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
